-- One-time seed for the existing course "Pub Golf Test" (game code WX5FF7).
-- Run this whole file in the Supabase SQL editor. Do not run a piece of it.
-- A successful run commits. Any error rolls the transaction back.
--
-- It does not change "Pub Golf: The SQL".
-- It stops if Pub Golf Test already has teams, players, holes, or results.
-- Team join codes are generated by the existing roster trigger. This script
-- does not choose them.
--
-- No schedule was supplied. start_time is left empty when the column allows
-- it, and blank otherwise, so the app shows "Time not set".
-- There is no par column. Pitcher holes reuse the live shape: score_type
-- custom, hole_type pitcher_race, primary_type pitcher_kill. Finish order
-- scores them (1st = 0, 2nd = +1, and so on). Normal holes use sips /
-- standard / normal. No extra pitcher settings are stored on the hole.

begin;

do $$
declare
  target_course uuid;
  original_course uuid;
  original_team_count integer;
  original_player_count integer;
  original_hole_count integer;
  original_score_count integer;
  existing_teams integer;
  existing_players integer;
  existing_holes integer;
  existing_scores integer;
  existing_results integer;
  start_time_required boolean;
  rule_text_required boolean;
  team_row record;
  new_team_id uuid;
  inserted_teams integer;
  inserted_players integer;
  inserted_holes integer;
begin
  select courses.id
    into target_course
  from public.courses
  where courses.title = 'Pub Golf Test'
    and lower(btrim(courses.join_code)) = 'wx5ff7'
  for update;

  if target_course is null then
    raise exception 'Pub Golf Test with game code WX5FF7 was not found. Nothing was changed.';
  end if;

  select courses.id
    into original_course
  from public.courses
  where courses.title = 'Pub Golf: The SQL';

  if original_course is null then
    raise exception 'Pub Golf: The SQL was not found. Nothing was changed.';
  end if;

  if original_course = target_course then
    raise exception 'The target course resolved to Pub Golf: The SQL. Nothing was changed.';
  end if;

  select count(*) into original_team_count from public.teams where course_id = original_course;
  select count(*) into original_player_count from public.players where course_id = original_course;
  select count(*) into original_hole_count from public.holes where course_id = original_course;
  select count(*) into original_score_count from public.scores where course_id = original_course;

  select count(*) into existing_teams from public.teams where course_id = target_course;
  select count(*) into existing_players from public.players where course_id = target_course;
  select count(*) into existing_holes from public.holes where course_id = target_course;
  select count(*) into existing_scores from public.scores where course_id = target_course;
  select
    (select count(*) from public.keg_stand_entries where course_id = target_course)
    + (select count(*) from public.pitcher_finishes where course_id = target_course)
    + (select count(*) from public.guinness_split_votes where course_id = target_course)
    + (select count(*) from public.bunker_hazard_entries where course_id = target_course)
    into existing_results;

  if existing_teams > 0
    or existing_players > 0
    or existing_holes > 0
    or existing_scores > 0
    or existing_results > 0 then
    raise exception
      'Pub Golf Test already has % teams, % players, % holes, % scores, and % other results. Nothing was changed.',
      existing_teams, existing_players, existing_holes, existing_scores, existing_results;
  end if;

  select attribute.attnotnull
    into start_time_required
  from pg_catalog.pg_attribute as attribute
  where attribute.attrelid = 'public.holes'::regclass
    and attribute.attname = 'start_time'
    and not attribute.attisdropped;

  select attribute.attnotnull
    into rule_text_required
  from pg_catalog.pg_attribute as attribute
  where attribute.attrelid = 'public.holes'::regclass
    and attribute.attname = 'rule_text'
    and not attribute.attisdropped;

  create temporary table seed_teams (
    sort_order integer primary key,
    theme text not null,
    team_id uuid
  ) on commit drop;

  insert into seed_teams (sort_order, theme)
  values
    (1, 'Red'),
    (2, 'Pink'),
    (3, 'Orange'),
    (4, 'Yellow'),
    (5, 'Green'),
    (6, 'Blue'),
    (7, 'Purple'),
    (8, 'Black');

  for team_row in
    select seed_teams.sort_order, seed_teams.theme
    from seed_teams
    order by seed_teams.sort_order
  loop
    insert into public.teams (course_id, theme)
    values (target_course, team_row.theme)
    returning id into new_team_id;

    update seed_teams
    set team_id = new_team_id
    where sort_order = team_row.sort_order;
  end loop;

  if exists (select 1 from seed_teams where team_id is null) then
    raise exception 'A team was not created. Nothing was kept.';
  end if;

  if exists (
    select 1
    from public.teams
    where teams.course_id = target_course
      and (
        teams.join_code is null
        or btrim(teams.join_code) = ''
        or char_length(btrim(teams.join_code)) <> 6
      )
  ) then
    raise exception 'A team did not receive a generated six-character join code. Nothing was kept.';
  end if;

  create temporary table seed_players (
    theme text not null,
    player_name text not null
  ) on commit drop;

  insert into seed_players (theme, player_name)
  values
    ('Red', 'Arion'),
    ('Red', 'Vinay'),
    ('Red', 'Skylar'),
    ('Red', 'Carly'),
    ('Red', 'Maddy'),
    ('Pink', 'Matt P.'),
    ('Pink', 'Mira'),
    ('Pink', 'Tyler'),
    ('Pink', 'Ani'),
    ('Pink', 'Audrey'),
    ('Orange', 'Aidan M.'),
    ('Orange', 'Brahm'),
    ('Orange', 'Emma'),
    ('Orange', 'Anaya'),
    ('Orange', 'Mia'),
    ('Yellow', 'Matt L.'),
    ('Yellow', 'Jojo'),
    ('Yellow', 'Gabe'),
    ('Yellow', 'Alyssa'),
    ('Yellow', 'Lauren'),
    ('Green', 'Milan'),
    ('Green', 'Sophia'),
    ('Green', 'Nick C.'),
    ('Green', 'Meaghan'),
    ('Green', 'Diya'),
    ('Blue', 'John'),
    ('Blue', 'Jack'),
    ('Blue', 'Mardi'),
    ('Blue', 'Ana'),
    ('Blue', 'Clem'),
    ('Purple', 'Caleb'),
    ('Purple', 'Alvin'),
    ('Purple', 'Kelechi'),
    ('Purple', 'Stefan'),
    ('Purple', 'Nick S.'),
    ('Black', 'Roan'),
    ('Black', 'Aidan S.'),
    ('Black', 'Emily'),
    ('Black', 'Rosa'),
    ('Black', 'Grace');

  insert into public.players (course_id, team_id, name)
  select target_course, seed_teams.team_id, seed_players.player_name
  from seed_players
  join seed_teams on seed_teams.theme = seed_players.theme;

  create temporary table seed_holes (
    hole_number integer primary key,
    bar_name text not null,
    address text not null,
    score_type text not null,
    hole_type text not null,
    primary_type text not null,
    rule_text text
  ) on commit drop;

  insert into seed_holes (
    hole_number, bar_name, address, score_type, hole_type, primary_type, rule_text
  )
  values
    (1, 'Freddy''s Bar', '627 5th Ave, Brooklyn, NY 11215', 'custom', 'pitcher_race', 'pitcher_kill',
      'Each team finishes one pitcher. Tap "Finish pitcher" once your team is done. Finish order sets score: 1st = 0, 2nd = +1, 3rd = +2, and so on.'),
    (2, 'Buttermilk Bar', '577 5th Ave, Brooklyn, NY 11215', 'sips', 'standard', 'normal', null),
    (3, 'Commonwealth', '497 5th Ave, Brooklyn, NY 11215', 'sips', 'standard', 'normal', null),
    (4, 'Smith''s Tavern', '440 5th Ave, Brooklyn, NY 11215', 'sips', 'standard', 'normal', null),
    (5, 'Logan''s Run', '375a 5th Ave, Brooklyn, NY 11215', 'sips', 'standard', 'normal', null),
    (6, 'The Gate', '321 5th Ave, Brooklyn, NY 11215', 'sips', 'standard', 'normal', null),
    (7, 'High Dive', '243 5th Ave, Brooklyn, NY 11215', 'sips', 'standard', 'normal', null),
    (8, 'Union Hall', '702 Union St, Brooklyn, NY 11215', 'sips', 'standard', 'normal', null),
    (9, 'Uncle Barry''s', '58 5th Ave, Brooklyn, NY 11217', 'custom', 'pitcher_race', 'pitcher_kill',
      'Each team finishes one pitcher. Tap "Finish pitcher" once your team is done. Finish order sets score: 1st = 0, 2nd = +1, 3rd = +2, and so on.');

  insert into public.holes (
    course_id,
    hole_number,
    bar_name,
    address,
    start_time,
    rule_text,
    score_type,
    hole_type,
    primary_type,
    has_bunker,
    has_water,
    has_guinness
  )
  select
    target_course,
    seed_holes.hole_number,
    seed_holes.bar_name,
    seed_holes.address,
    case when coalesce(start_time_required, false) then '' else null end,
    case
      when seed_holes.rule_text is not null then seed_holes.rule_text
      when coalesce(rule_text_required, false) then 'Submit your standard score for this hole.'
      else null
    end,
    seed_holes.score_type,
    seed_holes.hole_type,
    seed_holes.primary_type,
    false,
    false,
    false
  from seed_holes
  order by seed_holes.hole_number;

  select count(*) into inserted_teams from public.teams where course_id = target_course;
  select count(*) into inserted_players from public.players where course_id = target_course;
  select count(*) into inserted_holes from public.holes where course_id = target_course;

  if inserted_teams <> 8 or inserted_players <> 40 or inserted_holes <> 9 then
    raise exception
      'Expected 8 teams, 40 players, and 9 holes, and found % teams, % players, and % holes. Nothing was kept.',
      inserted_teams, inserted_players, inserted_holes;
  end if;

  if exists (
    select 1
    from public.teams
    where teams.course_id = target_course
    group by teams.course_id
    having count(distinct lower(btrim(teams.join_code))) <> 8
  ) then
    raise exception 'Team join codes were not unique. Nothing was kept.';
  end if;

  if exists (
    select 1
    from public.players
    where players.course_id = target_course
    group by players.team_id
    having count(*) <> 5
  ) then
    raise exception 'A team does not have five players. Nothing was kept.';
  end if;

  if exists (
    select 1
    from public.holes
    where holes.course_id = target_course
      and (
        (holes.hole_number in (1, 9) and (
          holes.primary_type is distinct from 'pitcher_kill'
          or holes.hole_type is distinct from 'pitcher_race'
          or holes.score_type is distinct from 'custom'
        ))
        or (holes.hole_number between 2 and 8 and (
          holes.primary_type is distinct from 'normal'
          or holes.hole_type is distinct from 'standard'
          or holes.score_type is distinct from 'sips'
        ))
      )
  ) then
    raise exception 'A hole was saved with the wrong scoring type. Nothing was kept.';
  end if;

  if (select count(*) from public.teams where course_id = original_course) <> original_team_count
    or (select count(*) from public.players where course_id = original_course) <> original_player_count
    or (select count(*) from public.holes where course_id = original_course) <> original_hole_count
    or (select count(*) from public.scores where course_id = original_course) <> original_score_count then
    raise exception 'Pub Golf: The SQL changed during the seed. Nothing was kept.';
  end if;
end $$;

commit;
